const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const API_ORIGIN='';
function apiUrl(url){return url.startsWith('/api/')?API_ORIGIN+url:url}
function mediaUrl(url=''){return String(url).startsWith('/api/')?API_ORIGIN+url:url}
function visitorId(){let id=localStorage.getItem('csboom_visitor_id');if(!id){const bytes=new Uint8Array(18);crypto.getRandomValues(bytes);id='v_'+[...bytes].map(b=>b.toString(16).padStart(2,'0')).join('');localStorage.setItem('csboom_visitor_id',id)}return id}
async function api(url,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json','X-CSBOOM-Visitor':visitorId()};const r=await fetch(apiUrl(url),opt);let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.detail||'Something went wrong');return d}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function safeUrl(v=''){try{const u=new URL(v,location.origin);return ['http:','https:','mailto:','tel:','line:'].includes(u.protocol)?u.href:'#'}catch{return '#'}}
const DEFAULT_BIO="I'm BOOM. I build clean, practical websites and capture real moments through photography. This portfolio brings together my coding work, photo projects, and the things I keep learning along the way.";
function displayBio(v=''){const text=String(v||'').trim();return !text||text.startsWith("I'm BOOM, a developer and photographer based in Thailand.")||text.startsWith('I build web applications that are fast')?DEFAULT_BIO:text}
function tags(arr=[]){return `<div class="tags">${(arr||[]).map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div>`}
function meta(name,content,prop=false){if(!content)return;let el=document.head.querySelector(`meta[${prop?'property':'name'}="${name}"]`);if(!el){el=document.createElement('meta');el.setAttribute(prop?'property':'name',name);document.head.appendChild(el)}el.content=content}
function applySeo({title,description,image}={}){if(title)document.title=title;if(description){meta('description',description);meta('og:description',description,true)}if(title){meta('og:title',title,true);meta('twitter:title',title)}if(description)meta('twitter:description',description);if(image){const img=safeUrl(mediaUrl(image));meta('og:image',img,true);meta('twitter:image',img)}meta('og:url',location.href,true);meta('twitter:card','summary_large_image');let canonical=document.head.querySelector('link[rel="canonical"]');if(canonical)canonical.href=location.href.split('#')[0]}
function skeletonCards(count=3){return Array.from({length:count},()=>'<article class="card skeleton-card"><div class="cover skeleton-box"></div><div class="card-body"><div class="skeleton-line short"></div><div class="skeleton-line"></div><div class="skeleton-line slim"></div></div></article>').join('')}
function masonrySkeleton(count=8){return `<div class="photo-grid skeleton-masonry">${Array.from({length:count},(_,i)=>`<div class="masonry-skeleton" style="aspect-ratio:${i%3===0?'3/4':i%3===1?'4/3':'1/1'}"></div>`).join('')}</div>`}
function friendlyError(message='Could not load this content.',retry='location.reload()'){return `<div class="empty error-state"><strong>${esc(message)}</strong><button class="btn secondary" type="button" onclick="${retry}">Try Again</button></div>`}
function toast(message){let box=$('#toastBox');if(!box){box=document.createElement('div');box.id='toastBox';box.className='toast-box';document.body.appendChild(box)}const item=document.createElement('div');item.className='toast';item.textContent=message;box.appendChild(item);setTimeout(()=>item.remove(),2600)}
function dateText(v=''){if(!v)return'';try{return new Intl.DateTimeFormat('en',{year:'numeric',month:'short',day:'numeric'}).format(new Date(v))}catch{return v}}
function projectStatus(p={}){return p.status||p.project_status||(p.demo_url?'Live':'Completed')}
function projectKind(p={}){const text=[p.category,p.type,p.title,p.summary,...(p.tech_stack||[])].join(' ').toLowerCase();if(/mobile|flutter|react native|android|ios/.test(text))return'Mobile';if(/iot|arduino|esp32|raspberry|sensor/.test(text))return'IoT';if(/api|fastapi|express|django|flask|backend|server|database|supabase/.test(text))return'Backend';if(/web|html|css|react|next|vue|frontend|javascript|typescript/.test(text))return'Web';return'Other'}
function projectCard(p={}){const slug=encodeURIComponent(p.slug||'');const tech=(p.tech_stack||[]).slice(0,6);return `<article class="card project-card-pro" data-kind="${esc(projectKind(p))}"><a class="card-media" href="/project.html?slug=${slug}">${p.cover_url?`<img class="cover" src="${esc(safeUrl(mediaUrl(p.cover_url)))}" loading="lazy" decoding="async" alt="${esc(p.title||'Project cover')}">`:`<div class="cover cover-fallback"><span>&lt;/&gt;</span></div>`}</a><div class="card-body"><div class="card-meta"><span class="status-pill">${esc(projectStatus(p))}</span><span>${esc(projectKind(p))}</span></div><h3><a href="/project.html?slug=${slug}">${esc(p.title)}</a></h3><p class="muted">${esc(p.summary||p.description||'')}</p>${tags(tech)}<div class="card-actions"><a class="btn secondary" href="/project.html?slug=${slug}">View Project</a>${p.source_url?`<a class="text-link" target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(p.source_url))}">GitHub ↗</a>`:''}${p.demo_url?`<a class="text-link" target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(p.demo_url))}">Live Demo ↗</a>`:''}</div></div></article>`}
function albumCard(a={},preview={}){const slug=encodeURIComponent(a.slug||'');const href=`/album.html?slug=${slug}`;const imgs=preview.photos||[];const count=a.photo_count||preview.count||imgs.length;const when=dateText(a.event_date||a.shoot_date||a.created_at);return `<article class="card album-card-mini" data-category="${esc(a.category||'Photography')}"><a class="album-mosaic" href="${href}">${imgs.length?imgs.slice(0,4).map((u,n)=>responsiveImage(u,{alt:`${a.title||'Album'} photo ${n+1}`,sizes:'(max-width:700px) 45vw, 22vw'})).join(''):`<div class="cover cover-fallback"><span>Photo</span></div>`}</a><div class="card-body"><div class="card-meta"><span>${esc(a.category||'Photography')}</span>${when?`<span>${esc(when)}</span>`:''}${count?`<span>${count} photos</span>`:''}</div><h3><a href="${href}">${esc(a.title)}</a></h3>${a.description?`<p class="muted">${esc(a.description)}</p>`:''}</div></article>`}
function albumCategory(a={}){const value=String(a.category||'').toLowerCase();if(value.includes('selected'))return'Selected Work';if(value.includes('graduat'))return'Graduation';if(value.includes('fashion'))return'Fashion';if(value.includes('studio'))return'Studio';if(value.includes('event'))return'Event';if(value.includes('portrait'))return'Portrait';return a.category||'Other'}
function imageVariant(url='',width=1200,quality=84){try{const u=new URL(mediaUrl(url),location.origin);u.searchParams.set('w',String(width));u.searchParams.set('q',String(quality));return u.origin===location.origin?u.pathname+u.search:u.href}catch{return mediaUrl(url)}}
function responsiveImage(url,{alt='',width=null,height=null,sizes='(max-width:700px) 50vw, 25vw',eager=false,className=''}={}){const lqip=imageVariant(url,64,45),src=imageVariant(url,eager?1600:960,84),srcset=[480,800,1200,1600,2000].map(w=>`${imageVariant(url,w,84)} ${w}w`).join(',');const dims=width&&height?` width="${esc(width)}" height="${esc(height)}"`:'';return `<img class="lqip-image ${esc(className)}" src="${esc(lqip)}" data-src="${esc(src)}" data-srcset="${esc(srcset)}" sizes="${esc(sizes)}" loading="${eager?'eager':'lazy'}" decoding="async" alt="${esc(alt)}"${dims}>`}
function initResponsiveImages(root=document){const images=$$('img[data-src]',root);const reveal=img=>{if(img.dataset.loaded)return;img.dataset.loaded='1';img.classList.add('is-developing');img.addEventListener('load',()=>{img.classList.remove('is-developing');img.classList.add('is-developed')},{once:true});img.srcset=img.dataset.srcset||'';img.src=img.dataset.src};if(!('IntersectionObserver'in window)){images.forEach(reveal);return}const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){observer.unobserve(entry.target);reveal(entry.target)}}),{rootMargin:'320px 0px',threshold:.01});images.forEach(img=>observer.observe(img))}
function setupFilters(container,items,{allLabel='All',attr,onFilter}){const el=$(container);if(!el)return;const detected=[...new Set(items.map(attr).filter(Boolean))];const values=container==='#albumFilters'?['Portrait','Event','Studio','Fashion','Graduation','Selected Work']:detected;if(container!=='#albumFilters'&&values.length<2){el.innerHTML='';return}el.innerHTML=[allLabel,...values].map((v,i)=>`<button class="filter-chip ${i===0?'active':''}" type="button" data-filter="${esc(v)}">${esc(v)}</button>`).join('');el.onclick=e=>{const b=e.target.closest('button');if(!b)return;$$('button',el).forEach(x=>x.classList.toggle('active',x===b));onFilter(b.dataset.filter===allLabel?null:b.dataset.filter)}}
function contactHandle(value=''){try{const u=new URL(value);return u.hostname.replace(/^www\./,'')+u.pathname.replace(/\/$/,'')}catch{return value}}
function contactHref(name,url){return name==='Instagram'?'/go/instagram':url}
function instagramMention(url=''){try{const u=new URL(url);const handle=u.pathname.split('/').filter(Boolean)[0];return handle?`@${handle}`:''}catch{return ''}}
function siteOrigin(){return (window.__siteSettings?.site_url||location.origin).replace(/\/$/,'')}
function albumSlugFromPath(){const parts=location.pathname.split('/').filter(Boolean);if(parts[0]==='photography'&&parts[1])return decodeURIComponent(parts[1]);if(parts[0]==='share'&&parts[1]==='photography'&&parts[2])return decodeURIComponent(parts[2]);return new URLSearchParams(location.search).get('slug')||''}
function photoIdFromPath(){const parts=location.pathname.split('/').filter(Boolean);if(parts[0]==='share'&&parts[1]==='photography'&&parts[3])return decodeURIComponent(parts[3]);return new URLSearchParams(location.search).get('photo')||''}
function albumPublicUrl(album=currentAlbum){return album?.slug?`${siteOrigin()}/album.html?slug=${encodeURIComponent(album.slug)}`:location.href.split('?')[0]}
function photoPublicUrl(photo=lightboxItems[lightboxIndex]){const base=albumPublicUrl(currentAlbum);if(!photo?.id)return base;const u=new URL(base);u.searchParams.set('photo',photo.id);return u.href}
function handoffUrl(photo=lightboxItems[lightboxIndex]){return currentAlbum?.slug&&photo?.id?`${siteOrigin()}/share/photography/${encodeURIComponent(currentAlbum.slug)}/${encodeURIComponent(photo.id)}`:photoPublicUrl(photo)}
function storyFileName(photo=lightboxItems[lightboxIndex]){const slug=(currentAlbum?.slug||'album').replace(/[^a-z0-9ก-๙_-]+/gi,'-').replace(/^-+|-+$/g,'')||'album';const pid=String(photo?.id||Date.now()).slice(0,12);return `csboom-${slug}-${pid}-story.png`}
function canNativeShareFiles(file){return !!(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]})))}
function isDesktopViewport(){return matchMedia('(min-width: 761px)').matches&&!matchMedia('(pointer: coarse)').matches}
function isMobileLineDevice(){return /Android|iPhone|iPad|iPod|Mobile|Windows Phone/i.test(navigator.userAgent)||matchMedia('(pointer: coarse)').matches}
function ensureLineModal(){let modal=$('#lineQrModal');if(modal)return modal;modal=document.createElement('div');modal.id='lineQrModal';modal.className='line-modal';modal.innerHTML='<div class="line-modal-card" role="dialog" aria-modal="true" aria-labelledby="lineModalTitle"><button class="line-modal-close" type="button" aria-label="Close">×</button><div class="eyebrow">LINE Contact</div><h2 id="lineModalTitle">Scan to add friend</h2><p class="muted">Scan the QR code with your phone, open LINE directly, or copy the link.</p><div class="line-qr-frame"><img alt="LINE QR Code"></div><div class="line-modal-actions"><a class="btn" target="_blank" rel="noopener noreferrer">Open LINE</a><button class="btn secondary" type="button">Copy link</button></div></div>';document.body.appendChild(modal);modal.addEventListener('click',e=>{if(e.target===modal)closeLineModal()});modal.querySelector('.line-modal-close').addEventListener('click',closeLineModal);modal.querySelector('button.btn.secondary').addEventListener('click',async()=>{const url=modal.dataset.lineUrl||'';try{await navigator.clipboard.writeText(url);modal.querySelector('button.btn.secondary').textContent='Copied'}catch{modal.querySelector('button.btn.secondary').textContent='Copy failed'}});return modal}
function openLineModal(url){const safe=safeUrl(mediaUrl(url));const modal=ensureLineModal();modal.dataset.lineUrl=safe;modal.querySelector('.line-qr-frame img').src=`https://api.qrserver.com/v1/create-qr-code/?size=240x240&margin=12&data=${encodeURIComponent(safe)}`;modal.querySelector('.line-modal-actions a').href=safe;modal.querySelector('button.btn.secondary').textContent='Copy link';modal.classList.add('open');document.body.style.overflow='hidden'}
function closeLineModal(){const modal=$('#lineQrModal');if(!modal)return;modal.classList.remove('open');document.body.style.overflow=''}
function initLineSmartLinks(){if(window.__lineSmartLinksReady)return;window.__lineSmartLinksReady=true;document.addEventListener('click',e=>{const link=e.target.closest('[data-line-link]');if(!link)return;if(isMobileLineDevice())return;e.preventDefault();openLineModal(link.href)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#lineQrModal')?.classList.contains('open'))closeLineModal()})}
function renderContactChannels(s={}){const grid=$('#contactChannels'),actions=$('#primaryContactActions');if(!grid&&!actions)return;const items=[
['Instagram',s.instagram_url,'Behind the scenes, photo work, and daily updates'],
['GitHub',s.github_url,'Code, repositories, and development projects'],
['Email',s.email?`mailto:${s.email}`:'','Project inquiries and collaboration'],
['Phone',s.phone?`tel:${String(s.phone).replace(/\s/g,'')}`:'','Direct call for urgent work'],
['LINE',s.line_url,'Quick chat and Thai-language contact'],
['Booking',s.booking_url,'Schedule a call or project discussion']
].filter(x=>x[1]);if(grid)grid.innerHTML=items.length?items.map(([name,url,desc])=>`<a class="contact-channel" ${name==='LINE'?'data-line-link':''} href="${esc(safeUrl(mediaUrl(contactHref(name,url))))}" target="${String(contactHref(name,url)).startsWith('mailto:')||String(contactHref(name,url)).startsWith('tel:')?'_self':'_blank'}" rel="noopener noreferrer"><span class="contact-channel-name">${esc(name)}</span><strong>${esc(contactHandle(url))}</strong><small>${esc(desc)}</small></a>`).join(''):'<div class="empty compact-empty">Add Instagram, GitHub, Email, or LINE from Admin.</div>';if(actions){const primary=items.filter(([name])=>['LINE','Instagram','GitHub','Email'].includes(name)).slice(0,3);actions.innerHTML=primary.length?primary.map(([name,url])=>`<a class="btn ${name==='Email'||name==='LINE'?'':'secondary'}" ${name==='LINE'?'data-line-link':''} href="${esc(safeUrl(mediaUrl(contactHref(name,url))))}" target="${String(contactHref(name,url)).startsWith('mailto:')?'_self':'_blank'}" rel="noopener noreferrer">${esc(name)} ↗</a>`).join(''):'<a class="btn secondary" href="/contact.html">Contact →</a>'}initLineSmartLinks()}
async function loadSettings(){try{const s=await api('/api/settings');window.__siteSettings=s;renderContactChannels(s);$$('[data-name]').forEach(e=>e.textContent=s.display_name||'BOOM');$$('[data-headline]').forEach(e=>e.textContent=s.headline||'Developer & Photographer');$$('[data-bio]').forEach(e=>e.textContent=displayBio(s.bio||e.textContent));$$('[data-email]').forEach(e=>{e.textContent=s.email||'';e.hidden=!s.email;if(e.tagName==='A')e.href=s.email?`mailto:${s.email}`:'#'});$$('[data-phone]').forEach(e=>{e.textContent=s.phone||'';e.hidden=!s.phone;if(e.tagName==='A')e.href=s.phone?`tel:${s.phone.replace(/\s/g,'')}`:'#'});$$('[data-location]').forEach(e=>{if(s.location)e.textContent=s.location;e.hidden=!s.location});$$('[data-contact-heading]').forEach(e=>e.textContent=s.contact_heading||"Let's create something together.");$$('[data-contact-intro]').forEach(e=>{if(s.contact_intro)e.textContent=s.contact_intro});$$('[data-availability]').forEach(e=>{if(s.availability_text)e.textContent=s.availability_text});const hero=$('.hero');if(hero&&s.hero_image_url)hero.style.backgroundImage=`linear-gradient(0deg,rgba(0,0,0,.62),rgba(0,0,0,.06)),url("${s.hero_image_url}")`;const p=$('[data-portrait]'),pf=$('[data-portrait-frame]');if(p&&pf&&s.hero_image_url){p.onload=()=>pf.classList.add('has-image');p.onerror=()=>pf.classList.remove('has-image');p.src=mediaUrl(s.hero_image_url)}const social=$('#contactSocials');if(social){const links=[['LINE',s.line_url],['Instagram',s.instagram_url],['Facebook',s.facebook_url],['GitHub',s.github_url],['LinkedIn',s.linkedin_url],['YouTube',s.youtube_url],['Booking',s.booking_url]].filter(x=>x[1]);social.innerHTML=links.map(([n,u])=>`<a class="contact-link" ${n==='LINE'?'data-line-link':''} href="${esc(safeUrl(mediaUrl(contactHref(n,u))))}" target="_blank" rel="noopener noreferrer">${esc(n)} <span>↗</span></a>`).join('')}if(s.default_og_image_url)meta('og:image',s.default_og_image_url,true)}catch{}}
async function loadProjects(target='#projectGrid',featured=null){const el=$(target);if(!el)return;el.innerHTML=skeletonCards(target==='#featuredProjects'?3:6);try{const qs=featured===null?'':`?featured=${featured}`;let rows=await api('/api/projects'+qs);if(featured===true&&rows.length===0)rows=(await api('/api/projects')).slice(0,3);if(target==='#featuredProjects')rows=rows.slice(0,3);const render=list=>{el.innerHTML=list.length?list.map(projectCard).join(''):'<div class="empty">No projects published yet.</div>'};render(rows);if(target==='#projectGrid')setupFilters('#projectFilters',rows,{attr:projectKind,onFilter:value=>render(value?rows.filter(p=>projectKind(p)===value):rows)})}catch(e){el.innerHTML=friendlyError("Couldn't load the projects.")}}
async function albumPreviewPhotos(a){try{const d=await api('/api/albums/'+encodeURIComponent(a.slug)+`?visitor_id=${encodeURIComponent(visitorId())}`);return {photos:(d.photos||[]).slice(0,4).map(p=>mediaUrl(p.image_url)),count:(d.photos||[]).length}}catch{return {photos:a.cover_url?[mediaUrl(a.cover_url)]:[],count:a.photo_count||0}}}
function featuredPhotoCard(p={},index=0){const href=`/album.html?slug=${encodeURIComponent(p.album_slug||'')}&photo=${encodeURIComponent(p.id||'')}`;const stats=[p.likes?`♥ ${p.likes}`:'',p.shares?`↗ ${p.shares}`:''].filter(Boolean).join(' · ');return `<a class="featured-photo ${index===0?'featured-lead':''}" href="${href}" aria-label="View ${esc(p.file_name||'featured photograph')} in ${esc(p.album_title||'album')}">${responsiveImage(p.image_url,{alt:p.alt_text||p.file_name||p.album_title||'Featured photography',width:p.width,height:p.height,sizes:index===0?'(max-width:620px) 100vw, 44vw':'(max-width:620px) 50vw, 28vw',eager:index<2})}<span class="featured-rank">${String(index+1).padStart(2,'0')}</span><span class="featured-overlay"><span class="featured-category">${esc(p.category||'Photography')}</span><strong>${esc(p.album_title||'Selected work')}</strong><small>${stats||'Rising selection'}</small></span></a>`}
async function loadFeaturedPhotography(){const el=$('#featuredPhotoGrid');if(!el)return;el.innerHTML=Array.from({length:5},(_,i)=>`<div class="featured-photo featured-skeleton ${i===0?'featured-lead':''}"></div>`).join('');try{const rows=await api('/api/photography/featured?limit=5');el.innerHTML=rows.length?rows.map(featuredPhotoCard).join(''):'<div class="empty">Featured photographs will appear as visitors interact with your work.</div>';initResponsiveImages(el)}catch{el.innerHTML=friendlyError("Couldn't load featured photography.")}}
async function loadAlbums(){const el=$('#albumGrid');if(!el)return;el.innerHTML=skeletonCards(3);try{let rows=await api('/api/albums');if(document.body.classList.contains('home-page'))rows=rows.slice(0,3);const previews=await Promise.all(rows.map(albumPreviewPhotos));const render=list=>{el.innerHTML=list.length?list.map((a)=>albumCard(a,previews[rows.indexOf(a)]||{})).join(''):'<div class="empty">No albums in this category yet.</div>';initResponsiveImages(el)};render(rows);setupFilters('#albumFilters',rows,{attr:albumCategory,onFilter:value=>render(value?rows.filter(a=>albumCategory(a)===value):rows)})}catch(e){el.innerHTML=friendlyError("Couldn't load the gallery.")}}
async function loadProject(){const el=$('#projectDetail');if(!el)return;const slug=new URLSearchParams(location.search).get('slug');if(!slug){el.innerHTML='<div class="empty">Project not found.</div>';return}el.innerHTML=skeletonCards(2);try{const p=await api('/api/projects/'+encodeURIComponent(slug));applySeo({title:(p.seo_title||p.title)+' — BOOM',description:p.seo_description||p.summary,image:p.cover_url});const shots=(p.screenshots||[]).filter(Boolean);const features=(p.features||[]).filter(Boolean);el.innerHTML=`<section class="project-hero detail-hero"><div><div class="eyebrow">Coding Project</div><h1 class="page-title">${esc(p.title)}</h1>${p.summary?`<p class="muted">${esc(p.summary)}</p>`:''}<div class="card-meta detail-meta"><span class="status-pill">${esc(projectStatus(p))}</span><span>${esc(projectKind(p))}</span></div>${tags(p.tech_stack)}<div class="detail-actions">${p.demo_url?`<a class="btn" target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(p.demo_url))}">Live Demo ↗</a>`:''}${p.source_url?`<a class="btn secondary" target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(p.source_url))}">GitHub ↗</a>`:''}</div></div>${p.cover_url?`<img src="${esc(safeUrl(mediaUrl(p.cover_url)))}" alt="${esc(p.title)}">`:''}</section><section class="section split project-story">${p.description?`<div><div class="eyebrow">Overview</div><p class="prose">${esc(p.description)}</p>${p.role?`<h2>My Role</h2><p class="prose">${esc(p.role)}</p>`:''}</div>`:''}<div>${p.problem?`<div class="eyebrow">Problem</div><p class="prose">${esc(p.problem)}</p>`:''}${p.solution?`<div class="eyebrow">Solution</div><p class="prose">${esc(p.solution)}</p>`:''}${features.length?`<div class="eyebrow">Key Features</div><ul class="prose">${features.map(f=>`<li>${esc(f)}</li>`).join('')}</ul>`:''}</div></section>${shots.length?`<section class="section"><div class="eyebrow">Screenshots / Gallery</div><div class="project-shots">${shots.map((u,i)=>`<img src="${esc(safeUrl(mediaUrl(u)))}" loading="lazy" decoding="async" alt="${esc(p.title)} screenshot ${i+1}">`).join('')}</div></section>`:''}`}catch(e){el.innerHTML=friendlyError("Couldn't load this project.")}}
let lightboxItems=[],lightboxIndex=0,touchStartX=0,touchStartY=0,lastTap=0,currentAlbum=null,currentStoryTemplate='minimal',storyOptions={textPosition:'auto',textColor:'auto',showQr:true},photoViewSeen=new Set();
let lightboxZoom=1,pinchStartDistance=0,pinchStartZoom=1,pinchActive=false;
function touchDistance(touches){if(touches.length<2)return 0;return Math.hypot(touches[0].clientX-touches[1].clientX,touches[0].clientY-touches[1].clientY)}
function applyLightboxZoom(){const l=$('#lightbox'),im=$('#lightboxImage');if(!l||!im)return;im.style.setProperty('--zoom',String(lightboxZoom));l.classList.toggle('is-zooming',lightboxZoom>1.01)}
function resetLightboxZoom(){lightboxZoom=1;pinchStartDistance=0;pinchActive=false;applyLightboxZoom()}
function updateLightboxCaption(){const p=lightboxItems[lightboxIndex],a=currentAlbum,meta=$('#lightboxAlbumMeta');if(!p||!a||!meta)return;meta.textContent=[a.category,dateText(a.event_date),p.alt_text||p.file_name].filter(Boolean).join(' · ')}
function initLightboxTouchZoom(){const im=$('#lightboxImage');if(!im||im.dataset.pinchReady)return;im.dataset.pinchReady='1';document.addEventListener('touchend',e=>{if(lightboxZoom>1.01&&e.target.closest?.('#lightbox')){e.stopPropagation();e.preventDefault()}},{capture:true,passive:false});im.addEventListener('touchstart',e=>{if(e.touches.length===2){pinchActive=true;pinchStartDistance=touchDistance(e.touches);pinchStartZoom=lightboxZoom;e.preventDefault()}},{passive:false});im.addEventListener('touchmove',e=>{if(!pinchActive||e.touches.length!==2)return;const distance=touchDistance(e.touches);if(!pinchStartDistance)return;lightboxZoom=Math.min(4,Math.max(1,pinchStartZoom*distance/pinchStartDistance));touchStartX=(e.touches[0].clientX+e.touches[1].clientX)/2;touchStartY=(e.touches[0].clientY+e.touches[1].clientY)/2;applyLightboxZoom();e.preventDefault()},{passive:false});im.addEventListener('touchend',e=>{if(pinchActive&&e.touches.length<2){pinchActive=false;if(lightboxZoom<1.08)resetLightboxZoom();e.preventDefault()}},{passive:false})}
function ensurePhotoMetadataChrome(){const l=$('#lightbox');if(!l||$('#lightboxExif'))return;l.insertAdjacentHTML('beforeend','<div class="photo-credit">Photography by <a href="https://www.instagram.com/cs.photo_byboom/" target="_blank" rel="noopener noreferrer">@cs.photo_byboom</a></div><button id="exifToggle" class="exif-toggle" type="button" aria-expanded="false" aria-controls="lightboxExif">Photo info</button><section id="lightboxExif" class="exif-sheet" aria-label="Photo information" hidden><div class="exif-sheet-head"><strong>Photo information</strong><button id="exifClose" type="button" aria-label="Close photo information">×</button></div><div id="exifContent" class="exif-content"><span>Loading…</span></div></section>');const toggle=$('#exifToggle'),sheet=$('#lightboxExif');const close=()=>{sheet.hidden=true;toggle.setAttribute('aria-expanded','false')};toggle.onclick=async()=>{const opening=sheet.hidden;sheet.hidden=!opening;toggle.setAttribute('aria-expanded',String(opening));if(opening)await loadCurrentExif()};$('#exifClose').onclick=close}
async function loadCurrentExif(){const p=lightboxItems[lightboxIndex],el=$('#exifContent');if(!p||!el)return;el.innerHTML='<span>Loading…</span>';try{const data=await api(`/api/photos/${encodeURIComponent(p.id)}/exif`);const labels={camera:'Camera',lens:'Lens',f_stop:'Aperture',shutter:'Shutter',iso:'ISO',focal_length:'Focal length'},rows=Object.entries(labels).filter(([key])=>data[key]);el.innerHTML=rows.length?rows.map(([key,label])=>`<div><small>${label}</small><strong>${esc(data[key])}</strong></div>`).join(''):'<span>EXIF data is not available for this photograph.</span>'}catch{el.innerHTML='<span>EXIF data is not available for this photograph.</span>'}}
