function ensureLightboxChrome(){const l=$('#lightbox');if(!l||l.dataset.ready)return;l.dataset.ready='1';l.insertAdjacentHTML('beforeend','<div class="lightbox-loader">Loading photo...</div><div class="heart-pop" id="heartPop">♥</div><div class="lightbox-info"><div><strong id="lightboxAlbumTitle"></strong><small id="lightboxAlbumMeta"></small></div><div id="lightboxCounter"></div></div><div class="lightbox-actions"><button id="lightboxLike" aria-label="Like photo" aria-pressed="false">♡</button><button id="lightboxShare" aria-label="Share photo" aria-expanded="false">↗ Share</button><button id="lightboxDownload" aria-label="Download photo">↓ Download</button></div><div id="shareMenu" class="share-menu" hidden role="dialog" aria-modal="false" aria-label="Share this photo"><div class="share-menu-head"><strong>Share this photo</strong><small id="sharePhotoLinkText"></small></div><img id="photoQr" class="photo-qr" alt="Scan on phone to share this photo"><button id="storyBtn" type="button">Instagram Story</button><button id="nativeShare" type="button">Share Photo</button><button id="copyPhotoLink" type="button">Copy Photo Link</button><button id="shareAlbum" type="button">Copy Album Link</button><button id="downloadFromShare" type="button">Download Photo</button></div><div id="storyPanel" class="story-panel" hidden><div class="story-tools"><div class="story-ready"><div class="eyebrow">Story Ready</div><h2>Your Story is ready</h2><p id="storyInstruction" class="muted">Make your Story clickable: copy the photo link, share the image, then add it in Instagram Sticker → Link.</p><input id="storyLinkInput" class="story-link-input" readonly aria-label="Photo link for Instagram Link Sticker"><div class="story-command-row"><button id="copyStoryLink" type="button">Copy Photo Link</button><button id="postStoryInstagram" type="button">Share Story</button></div></div><div class="story-style-grid"><button data-story="minimal">Minimal</button><button data-story="full">Full Photo</button><button data-story="editorial">Editorial</button><button data-story="poster">Poster</button><button data-story="polaroid">Polaroid</button><button data-story="split">Split</button><button data-story="dark">Dark</button><button data-story="clean">Clean</button></div><label class="story-text-field">Custom text<textarea id="storyText" maxlength="90" placeholder="พิมพ์ข้อความบน Story..."></textarea></label><div class="story-control-group"><span>Text position</span><div class="story-segment"><button data-story-pos="auto" class="active">Auto</button><button data-story-pos="top">Top</button><button data-story-pos="center">Center</button><button data-story-pos="bottom">Bottom</button></div></div><div class="story-control-group"><span>Text color</span><div class="story-swatch-row"><button data-story-color="auto" class="active">Auto</button><button data-story-color="white" aria-label="White text"></button><button data-story-color="black" aria-label="Black text"></button><button data-story-color="gold" aria-label="Gold text"></button><button data-story-color="cream" aria-label="Cream text"></button></div></div><label class="story-toggle"><input id="storyQrToggle" type="checkbox" checked><span>Show QR code</span></label><div class="story-command-row"><button id="saveStory">Download Story Image</button><button id="copyStoryCaption">Copy Caption</button><button id="closeStory">Close</button></div></div><canvas id="storyCanvas" width="1080" height="1920"></canvas></div>');$('#lightboxLike').onclick=toggleLike;$('#lightboxShare').onclick=openShareMenu;$('#copyPhotoLink').onclick=copyPhotoLink;$('#nativeShare').onclick=nativeSharePhoto;$('#shareAlbum').onclick=shareAlbumLink;$('#downloadFromShare').onclick=downloadCurrentPhoto;$('#storyBtn').onclick=openStoryShareFlow;$$('[data-story]').forEach(b=>b.onclick=()=>openStory(b.dataset.story));$('#storyText').oninput=()=>openStory(currentStoryTemplate,{quiet:true});$$('[data-story-pos]').forEach(b=>b.onclick=()=>{storyOptions.textPosition=b.dataset.storyPos;openStory(currentStoryTemplate,{quiet:true})});$$('[data-story-color]').forEach(b=>b.onclick=()=>{storyOptions.textColor=b.dataset.storyColor;openStory(currentStoryTemplate,{quiet:true})});$('#storyQrToggle').onchange=e=>{storyOptions.showQr=e.target.checked;openStory(currentStoryTemplate,{quiet:true})};$('#saveStory').onclick=saveStory;$('#postStoryInstagram').onclick=postStoryInstagram;$('#copyStoryCaption').onclick=copyStoryCaption;$('#copyStoryLink').onclick=copyStoryLink;$('#closeStory').onclick=()=>$('#storyPanel').hidden=true;$('#lightboxDownload').onclick=downloadCurrentPhoto;$('#lightboxImage').addEventListener('dblclick',()=>likeCurrent(true));$('#lightboxImage').addEventListener('click',()=>{const now=Date.now();if(now-lastTap<320)likeCurrent(true);lastTap=now});$('#lightboxImage').addEventListener('load',()=>$('#lightbox').classList.remove('is-loading'));$('#lightboxImage').addEventListener('error',()=>{toast("Couldn't load this photo.");$('#lightbox').classList.remove('is-loading')})}
function photoUrl(photo=lightboxItems[lightboxIndex]){return photoPublicUrl(photo)}
