function openLightbox(items,index,{replace=false}={}){ensureLightboxChrome();ensurePhotoMetadataChrome();initLightboxTouchZoom();resetLightboxZoom();lightboxItems=items;lightboxIndex=index;const l=$('#lightbox');if(!l)return;l.classList.add('open');document.body.style.overflow='hidden';document.documentElement.classList.add('lightbox-lock');renderLightbox();updateLightboxCaption();updateHistory(replace);$('#lightboxClose')?.focus()}
function renderLightbox(){const p=lightboxItems[lightboxIndex],a=currentAlbum,im=$('#lightboxImage');if(!p||!im)return;$('#lightbox').classList.add('is-loading');setLightboxSource(p,im);im.alt=p.alt_text||p.file_name||a.title;$('#lightboxAlbumTitle').textContent=a.title||'';$('#lightboxAlbumMeta').textContent=[a.category,dateText(a.event_date)].filter(Boolean).join(' · ');$('#lightboxCounter').textContent=`${lightboxIndex+1} / ${lightboxItems.length}`;$('#lightboxLike').hidden=!a.show_likes;$('#lightboxLike').textContent=`${p.liked_by_visitor?'♥':'♡'} ${Math.max(0,p.like_count||0)}`;$('#lightboxLike').setAttribute('aria-pressed',String(!!p.liked_by_visitor));$('#lightboxDownload').hidden=!a.allow_downloads;$('#lightboxShare').hidden=!a.allow_sharing;$('#shareMenu').hidden=true;$('#lightboxExif')&&($('#lightboxExif').hidden=true);$('#exifToggle')?.setAttribute('aria-expanded','false');const qr=$('#photoQr');if(qr)qr.src=qrUrl(photoUrl(p));prefetchNeighbor();if(!photoViewSeen.has(p.id)){photoViewSeen.add(p.id);api(`/api/photos/${encodeURIComponent(p.id)}/event`,{method:'POST',body:JSON.stringify({anonymous_visitor_id:visitorId(),event_type:'photo_view'})}).catch(()=>{})}applySeo({title:`${a.title} — CS.BOOM Photography`,description:a.description,image:p.image_url})}
