function closeLightbox(){const l=$('#lightbox');if(l)l.classList.remove('open');resetLightboxZoom();document.body.style.overflow='';document.documentElement.classList.remove('lightbox-lock');$('#storyPanel')&&($('#storyPanel').hidden=true);$('#shareMenu')&&($('#shareMenu').hidden=true);closeDesktopHandoff();const u=new URL('/album.html',location.origin);u.searchParams.set('slug',currentAlbum?.slug||albumSlugFromPath());history.pushState({},'',u)}
function prefetchNeighbor(){[-1,1].forEach(step=>{const p=lightboxItems[(lightboxIndex+step+lightboxItems.length)%lightboxItems.length];if(p){const img=new Image();img.src=mediaUrl(p.image_url)}})}
function heartPop(){const h=$('#heartPop');if(!h)return;h.classList.remove('show');void h.offsetWidth;h.classList.add('show')}
async function likeCurrent(forceLike=false){const p=lightboxItems[lightboxIndex],a=currentAlbum;if(!p||!a.show_likes)return;const was=!!p.liked_by_visitor;if(forceLike&&was){heartPop();return}p.liked_by_visitor=forceLike?true:!was;p.like_count=Math.max(0,(p.like_count||0)+(p.liked_by_visitor&&!was?1:(!p.liked_by_visitor&&was?-1:0)));renderLightbox();if(p.liked_by_visitor)heartPop();try{const method=p.liked_by_visitor?'POST':'DELETE';const d=await api(`/api/photos/${encodeURIComponent(p.id)}/like`,{method,body:JSON.stringify({anonymous_visitor_id:visitorId()})});p.liked_by_visitor=d.liked;p.like_count=d.like_count;renderLightbox()}catch(e){p.liked_by_visitor=was;p.like_count=Math.max(0,(p.like_count||0)+(was?1:-1));renderLightbox();toast('Like failed')}}
function toggleLike(){likeCurrent(false)}
async function downloadCurrentPhoto(){const p=lightboxItems[lightboxIndex];if(!p)return;try{const r=await fetch(apiUrl(`/api/photos/${encodeURIComponent(p.id)}/download?visitor_id=${encodeURIComponent(visitorId())}`));if(!r.ok)throw new Error('Download failed');const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(r.headers.get('Content-Disposition')||'').match(/filename=\"(.+)\"/)?.[1]||'CSBOOM_Photo.jpg';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Downloaded ✓')}catch(e){toast(e.message||'Download failed')}}
function openShareMenu(forceOpen=null){const menu=$('#shareMenu'),p=lightboxItems[lightboxIndex];if(!menu||!p)return;const next=forceOpen===null?menu.hidden:!!forceOpen;menu.hidden=!next;$('#lightboxShare')?.setAttribute('aria-expanded',String(next));const text=$('#sharePhotoLinkText');if(text)text.textContent=new URL(photoUrl(p)).pathname+new URL(photoUrl(p)).search;const qr=$('#photoQr');if(qr)qr.src=qrUrl(isDesktopViewport()?handoffUrl(p):photoUrl(p))}
function ensureDesktopHandoffModal(){let modal=$('#storyHandoffModal');if(modal)return modal;modal=document.createElement('div');modal.id='storyHandoffModal';modal.className='handoff-modal';modal.innerHTML='<div class="handoff-card" role="dialog" aria-modal="true" aria-labelledby="handoffTitle"><button class="handoff-close" type="button" aria-label="Close">×</button><div class="eyebrow">Instagram Story</div><h2 id="handoffTitle">Continue on your phone</h2><p class="muted">Scan this with your phone. It opens the same photo with the Story tools ready.</p><div class="handoff-qr-wrap"><img id="handoffQr" alt="QR code to continue on phone"></div><input id="handoffLinkInput" class="story-link-input" readonly aria-label="Photo link"><div class="handoff-actions"><button id="handoffCopyLink" class="btn secondary" type="button">Copy Photo Link</button><button id="handoffDownloadStory" class="btn" type="button">Download Story Image</button></div></div>';document.body.appendChild(modal);modal.addEventListener('click',e=>{if(e.target===modal)closeDesktopHandoff()});modal.querySelector('.handoff-close').onclick=closeDesktopHandoff;modal.querySelector('#handoffCopyLink').onclick=copyPhotoLink;modal.querySelector('#handoffDownloadStory').onclick=()=>openStory('minimal');return modal}
function closeDesktopHandoff(){const modal=$('#storyHandoffModal');if(!modal)return;modal.classList.remove('open');document.body.classList.remove('handoff-open')}
function openDesktopHandoff(){const p=lightboxItems[lightboxIndex];if(!p)return;const modal=ensureDesktopHandoffModal();$('#shareMenu')&&($('#shareMenu').hidden=true);modal.querySelector('#handoffQr').src=qrUrl(handoffUrl(p));modal.querySelector('#handoffLinkInput').value=photoUrl(p);modal.classList.add('open');document.body.classList.add('handoff-open');modal.querySelector('#handoffCopyLink')?.focus();toast('Scan QR with your phone')}
