async function copyPhotoLink(){const p=lightboxItems[lightboxIndex];if(!p)return;const ok=await copyText(photoUrl(p));api(`/api/photos/${p.id}/event`,{method:'POST',body:JSON.stringify({anonymous_visitor_id:visitorId(),event_type:'share'})}).catch(()=>{});toast(ok?'Photo link copied ✓':'Copy failed')}
async function nativeSharePhoto(){const p=lightboxItems[lightboxIndex],url=photoUrl(p);try{if(navigator.share){await navigator.share({title:currentAlbum.title,text:'CS.BOOM Photography',url});toast('Shared ✓')}else await copyPhotoLink()}catch{}}
function openStoryShareFlow(){const p=lightboxItems[lightboxIndex];if(!p)return;api(`/api/photos/${p.id}/event`,{method:'POST',body:JSON.stringify({anonymous_visitor_id:visitorId(),event_type:'share'})}).catch(()=>{});if(isDesktopViewport()){openDesktopHandoff();return}openStory('minimal')}
async function shareAlbumLink(){const ok=await copyText(albumPublicUrl(currentAlbum));toast(ok?'Album link copied ✓':'Copy failed')}
async function openStory(template='minimal',{quiet=false}={}){currentStoryTemplate=template;$$('[data-story]').forEach(b=>b.classList.toggle('active',b.dataset.story===template));$$('[data-story-pos]').forEach(b=>b.classList.toggle('active',b.dataset.storyPos===storyOptions.textPosition));$$('[data-story-color]').forEach(b=>b.classList.toggle('active',b.dataset.storyColor===storyOptions.textColor));const qrToggle=$('#storyQrToggle');if(qrToggle)qrToggle.checked=storyOptions.showQr;const p=lightboxItems[lightboxIndex];if(!p)return;$('#storyPanel').hidden=false;const link=$('#storyLinkInput');if(link)link.value=photoUrl(p);setStoryReadyState(false);const shareBtn=$('#postStoryInstagram');if(shareBtn)shareBtn.textContent=isDesktopViewport()?'Download Story Image':'Share Story';const c=$('#storyCanvas'),ctx=c.getContext('2d'),img=new Image(),qr=new Image();let photoReady=false,qrReady=false;img.crossOrigin='anonymous';qr.crossOrigin='anonymous';const draw=()=>{if(!photoReady)return;drawStory(ctx,c,img,template,p,qrReady?qr:null);if(!quiet)toast('Story preview ready')};img.onload=()=>{photoReady=true;draw()};qr.onload=()=>{qrReady=true;draw()};qr.onerror=draw;img.onerror=()=>toast('Could not build story');qr.src=localQrUrl(photoUrl(p));img.src=mediaUrl(p.image_url)}
function drawCover(ctx,img,x,y,w,h){const s=Math.max(w/img.width,h/img.height),sw=w/s,sh=h/s,sx=(img.width-sw)/2,sy=(img.height-sh)/2;ctx.drawImage(img,sx,sy,sw,sh,x,y,w,h)}
function drawContain(ctx,img,x,y,w,h,bg='rgba(255,255,255,.04)'){if(bg){ctx.fillStyle=bg;ctx.fillRect(x,y,w,h)}const s=Math.min(w/img.width,h/img.height),dw=img.width*s,dh=img.height*s,dx=x+(w-dw)/2,dy=y+(h-dh)/2;ctx.drawImage(img,dx,dy,dw,dh);return{x:dx,y:dy,w:dw,h:dh}}
function wrapCanvasText(ctx,text,maxWidth,maxLines=2){const words=String(text||'').split(/\s+/).filter(Boolean),lines=[];let line='';for(const w of words){const test=line?line+' '+w:w;if(ctx.measureText(test).width<=maxWidth){line=test;continue}if(line){lines.push(line);line=''}if(ctx.measureText(w).width<=maxWidth){line=w;continue}let part='';for(const ch of Array.from(w)){const next=part+ch;if(ctx.measureText(next).width<=maxWidth)part=next;else{if(part)lines.push(part);part=ch}}line=part}if(line)lines.push(line);if(lines.length>maxLines){lines.length=maxLines;while(lines[maxLines-1]&&ctx.measureText(lines[maxLines-1]+'...').width>maxWidth)lines[maxLines-1]=lines[maxLines-1].slice(0,-1);lines[maxLines-1]=(lines[maxLines-1]||'').trim()+'...'}return lines}
function fitCanvasText(ctx,text,maxWidth,maxLines,size,minSize,weight='900'){for(let s=size;s>=minSize;s-=2){ctx.font=`${weight} ${s}px Outfit, sans-serif`;const lines=wrapCanvasText(ctx,text,maxWidth,maxLines);if(lines.length<maxLines||!lines[lines.length-1]?.endsWith('...'))return{lines,size:s}}ctx.font=`${weight} ${minSize}px Outfit, sans-serif`;return{lines:wrapCanvasText(ctx,text,maxWidth,maxLines),size:minSize}}
function drawAlbumTitle(ctx,text,x,y,maxWidth,maxLines=3,size=64,minSize=30,lineHeight=null,color='#fff',weight='900'){ctx.fillStyle=color;const fitted=fitCanvasText(ctx,text,maxWidth,maxLines,size,minSize,weight);ctx.font=`${weight} ${fitted.size}px Outfit, sans-serif`;const gap=lineHeight||Math.round(fitted.size*1.12);fitted.lines.forEach((line,i)=>ctx.fillText(line,x,y+i*gap))}
function drawStoryLinkBadge(ctx,p,x,y,w,h,dark=false){ctx.fillStyle=dark?'rgba(255,255,255,.92)':'rgba(8,10,7,.86)';ctx.fillRect(x,y,w,h);ctx.fillStyle=dark?'#111':'#fff';ctx.font='800 24px Outfit, sans-serif';ctx.fillText('PHOTO LINK',x+22,y+42);ctx.font='500 22px Outfit, sans-serif';ctx.fillText(new URL(photoUrl(p)).host,x+22,y+78)}
function storyColor(defaultColor){return {white:'#fff',black:'#111',gold:'#d9a75d',cream:'#fff8ed'}[storyOptions.textColor]||defaultColor}
function storyTextY(defaultY){const zones={full:{top:260,center:930,bottom:1486},editorial:{top:170,center:1370,bottom:1688},poster:{top:112,center:1468,bottom:1748},polaroid:{top:118,center:1248,bottom:1456},split:{top:1040,center:760,bottom:1260},dark:{top:380,center:930,bottom:1430},clean:{top:84,center:1200,bottom:1428},minimal:{top:110,center:1450,bottom:1662}};return zones[currentStoryTemplate]?.[storyOptions.textPosition]||defaultY}
function drawCustomText(ctx,text,x,y,maxWidth,color='#fff',size=44){if(!text)return;ctx.fillStyle=storyColor(color);ctx.font=`800 ${size}px Outfit, sans-serif`;ctx.shadowColor=storyColor(color)==='#111'?'rgba(255,255,255,.28)':'rgba(0,0,0,.45)';ctx.shadowBlur=10;wrapCanvasText(ctx,text,maxWidth,3).forEach((line,i)=>ctx.fillText(line,x,storyTextY(y)+i*(size+12)));ctx.shadowBlur=0}
function drawQr(ctx,p,qr,x=806,y=1636,size=194){if(!storyOptions.showQr)return;if(qr){ctx.fillStyle='#fff';ctx.fillRect(x,y,size,size);ctx.drawImage(qr,x+18,y+18,size-36,size-36)}else drawStoryLinkBadge(ctx,p,x-86,y+8,270,112,true)}
function drawStory(ctx,c,img,t,p,qr){const custom=($('#storyText')?.value||'').trim();ctx.fillStyle='#080a07';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#fff8ed';ctx.font='700 44px Outfit, sans-serif';if(t==='full'){drawContain(ctx,img,0,0,c.width,c.height);const g=ctx.createLinearGradient(0,1280,0,1920);g.addColorStop(0,'rgba(0,0,0,0)');g.addColorStop(.5,'rgba(0,0,0,.58)');g.addColorStop(1,'rgba(0,0,0,.86)');ctx.fillStyle='rgba(0,0,0,.26)';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle=g;ctx.fillRect(0,1280,c.width,640);ctx.fillStyle='#fff';ctx.font='700 44px Outfit, sans-serif';ctx.fillText('SHOT BY CS.BOOM',72,150);drawAlbumTitle(ctx,currentAlbum.title,72,1648,620,3,42,28,50,'#fff','800');drawCustomText(ctx,custom,72,1486,620,'#fff',46);ctx.font='500 26px Outfit, sans-serif';ctx.fillText(new URL(photoUrl(p)).host,72,1816);drawQr(ctx,p,qr,820,1588,188);return}if(t==='editorial'){ctx.fillStyle='#f6f1e8';ctx.fillRect(0,0,c.width,c.height);drawContain(ctx,img,90,260,900,1100);ctx.fillStyle='#161817';drawAlbumTitle(ctx,currentAlbum.title.toUpperCase(),90,1415,760,3,70,34,66,'#161817','900');ctx.font='500 34px Outfit, sans-serif';ctx.fillText([currentAlbum.category,dateText(currentAlbum.event_date)].filter(Boolean).join(' · '),90,1628);ctx.fillText('CS.BOOM Photography',90,1768);drawCustomText(ctx,custom,90,1688,600,'#161817',38);drawQr(ctx,p,qr)}else if(t==='poster'){ctx.fillStyle='#111';ctx.fillRect(0,0,c.width,c.height);drawContain(ctx,img,70,170,940,1250);ctx.strokeStyle='#d9a75d';ctx.lineWidth=6;ctx.strokeRect(70,170,940,1250);ctx.fillStyle='#fff8ed';drawAlbumTitle(ctx,currentAlbum.title.toUpperCase(),82,1550,760,3,80,36,84,'#fff8ed','900');drawCustomText(ctx,custom,82,1732,650,'#e2ac61',44);drawQr(ctx,p,qr)}else if(t==='polaroid'){ctx.fillStyle='#efe8da';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#fff';ctx.fillRect(92,190,896,1220);drawContain(ctx,img,132,230,816,980);ctx.fillStyle='#141414';ctx.font='800 52px Outfit, sans-serif';ctx.fillText('CS.BOOM',132,1310);drawAlbumTitle(ctx,custom||currentAlbum.title,132,1370,740,3,34,22,42,'#141414','600');drawQr(ctx,p,qr,760,1540,210)}else if(t==='split'){ctx.fillStyle='#070807';ctx.fillRect(0,0,c.width,c.height);drawContain(ctx,img,0,0,540,c.height);ctx.fillStyle='#f4efe6';ctx.fillRect(540,0,540,c.height);ctx.fillStyle='#111';drawAlbumTitle(ctx,currentAlbum.title.toUpperCase(),600,360,390,5,68,30,72,'#111','900');drawCustomText(ctx,custom,600,760,360,'#6b4b23',42);drawQr(ctx,p,qr,700,1480,220)}else if(t==='dark'){drawContain(ctx,img,0,0,c.width,c.height);ctx.fillStyle='rgba(0,0,0,.62)';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#fff';ctx.font='900 86px Outfit, sans-serif';ctx.fillText('CS.BOOM',72,250);drawAlbumTitle(ctx,custom||currentAlbum.title,72,1430,720,4,58,28,66,'#fff','900');drawQr(ctx,p,qr,808,1628,194)}else if(t==='clean'){ctx.fillStyle='#fbfaf7';ctx.fillRect(0,0,c.width,c.height);drawContain(ctx,img,120,170,840,980);ctx.fillStyle='#111';drawAlbumTitle(ctx,currentAlbum.title,120,1260,760,3,62,30,68,'#111','900');drawCustomText(ctx,custom,120,1428,680,'#555',42);drawQr(ctx,p,qr,778,1588,210)}else{drawContain(ctx,img,90,210,900,1180);ctx.fillText('CS.BOOM',90,1520);drawAlbumTitle(ctx,currentAlbum.title,90,1585,760,3,34,24,42,'#fff8ed','500');drawCustomText(ctx,custom,90,1662,600,'#fff8ed',42);drawQr(ctx,p,qr)}ctx.font='500 26px Outfit, sans-serif';ctx.fillStyle=t==='clean'||t==='editorial'||t==='polaroid'||t==='split'?'#111':'#fff8ed';ctx.fillText(new URL(photoUrl(p)).host,90,1840)}
async function copyText(text){try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);return true}}catch{}const ta=document.createElement('textarea');ta.value=text;ta.setAttribute('readonly','');ta.style.position='fixed';ta.style.top='-1000px';document.body.appendChild(ta);ta.focus();ta.select();let ok=false;try{ok=document.execCommand('copy')}catch{}ta.remove();return ok}
async function copyStoryLink(){const p=lightboxItems[lightboxIndex];if(!p)return;const ok=await copyText(photoUrl(p));if(ok)setStoryReadyState(true);else{const inst=$('#storyInstruction');if(inst)inst.textContent='Copy failed. Select the link field and copy it manually.';$('#storyLinkInput')?.select()}toast(ok?'Photo link copied ✓':'Copy failed')}
function storyCaption(){const custom=($('#storyText')?.value||'').trim(),mention=instagramMention(window.__siteSettings?.instagram_url);return [custom,currentAlbum?.title,`Shot by ${mention||'CS.BOOM'}`].filter(Boolean).join('\n')}
async function copyStoryCaption(){const ok=await copyText(storyCaption());toast(ok?'Caption copied ✓':'Copy failed')}
function storyBlob(){return new Promise((resolve,reject)=>{$('#storyCanvas')?.toBlob(blob=>blob?resolve(blob):reject(new Error('Story save failed')),'image/png')})}
function downloadBlob(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200)}
async function downloadStoryImage(){try{const blob=await storyBlob();downloadBlob(blob,storyFileName());toast('Story image downloaded ✓');return blob}catch(e){toast('Story save failed');return null}}
function saveStory(){downloadStoryImage()}
async function postStoryInstagram(){const p=lightboxItems[lightboxIndex];if(p)api(`/api/photos/${p.id}/event`,{method:'POST',body:JSON.stringify({anonymous_visitor_id:visitorId(),event_type:'share'})}).catch(()=>{});let blob;try{blob=await storyBlob()}catch(e){toast('Story save failed');return}const file=new File([blob],storyFileName(p),{type:'image/png'});if(isDesktopViewport()){downloadBlob(blob,file.name);toast('Story image downloaded. Scan QR or send it from your phone.');return}try{if(canNativeShareFiles(file)){await navigator.share({files:[file],title:currentAlbum?.title||'CS.BOOM Story'});toast('Choose Instagram or Stories in the share sheet');return}}catch(e){if(e.name==='AbortError')return}downloadBlob(blob,file.name);toast('Story image saved. Open Instagram and upload it to your Story.')}
async function loadAlbum(){
  const el=$('#albumDetail');
  if(!el)return;
  const slug=albumSlugFromPath();
  if(!slug){el.innerHTML='<div class="empty">Album not found.</div>';return}
  const isHandoff=location.pathname.startsWith('/share/photography/');
  el.innerHTML=masonrySkeleton(innerWidth<=380?3:innerWidth<=700?6:8);
  try{
    const a=await api('/api/albums/'+encodeURIComponent(slug)+`?visitor_id=${encodeURIComponent(visitorId())}`);
    currentAlbum=a;
    applySeo({title:(a.seo_title||a.title)+' — BOOM',description:a.seo_description||a.description,image:a.cover_url});
    api('/api/albums/view',{method:'POST',body:JSON.stringify({album_id:a.id,anonymous_visitor_id:visitorId()})}).catch(()=>{});
    const photos=a.photos||[];
    const when=dateText(a.event_date||a.shoot_date||a.created_at);
    el.innerHTML=`<div class="section-head album-head"><div><div class="eyebrow">${esc(a.category||'Photography')}${when?` • ${esc(when)}`:''}</div><h1 class="page-title">${esc(a.title)}</h1>${a.description?`<p class="muted">${esc(a.description)}</p>`:''}</div>${a.allow_sharing?'<button class="btn secondary" id="albumShareBtn" type="button">Share Album</button>':''}</div>${isHandoff?'<div class="handoff-note"><strong>Ready to share</strong><span>Copy the photo link, then share the Story image from your phone.</span></div>':''}${photos.length?`<div class="photo-grid">${photos.map((p,i)=>`<button class="photo-tile" type="button" data-i="${i}" aria-label="Open photo ${i+1}">${responsiveImage(p.image_url,{alt:p.alt_text||p.file_name||a.title,width:p.width,height:p.height,sizes:"(max-width:380px) 100vw, (max-width:700px) 50vw, (max-width:1100px) 33vw, 25vw"})}</button>`).join('')}</div>`:'<div class="empty">No photos available yet.</div>'}`;
    initResponsiveImages(el);
    $('#albumShareBtn')?.addEventListener('click',shareAlbumLink);
    $$('.photo-tile').forEach(btn=>btn.onclick=()=>openLightbox(photos,+btn.dataset.i));
    const direct=photoIdFromPath();
    if(direct){
      const idx=photos.findIndex(p=>p.id===direct);
      if(idx>=0){
        openLightbox(photos,idx,{replace:!isHandoff});
        if(isHandoff&&!isDesktopViewport())setTimeout(()=>openStory('minimal'),450);
      }else{
        toast('Photo not found');
      }
    }
  }catch(e){
    el.innerHTML=friendlyError("Couldn't load the gallery.");
  }
}
async function loadHomeStats(){const projectEl=$('#homeProjectCount'),photoEl=$('#homePhotoCount'),ideaEl=$('#homeIdeaCount');if(!projectEl&&!photoEl&&!ideaEl)return;try{const projects=await api('/api/projects');const albums=await api('/api/albums');let photoCount=0;await Promise.all((albums||[]).map(async a=>{try{const detail=await api('/api/albums/'+encodeURIComponent(a.slug));photoCount+=(detail.photos||[]).length}catch{}}));if(projectEl)projectEl.textContent=String((projects||[]).length);if(photoEl)photoEl.textContent=String(photoCount);if(ideaEl)ideaEl.textContent=String((projects||[]).length+photoCount+(albums||[]).length)}catch{if(projectEl)projectEl.textContent='0';if(photoEl)photoEl.textContent='0';if(ideaEl)ideaEl.textContent='0'}}
function initActiveNav(){const clean=p=>p==='/'?'/':p.replace(/\.html$/,'').replace(/\/$/,'');const path=clean(location.pathname);$$('.nav-links a').forEach(a=>{const href=clean(new URL(a.getAttribute('href')||'#',location.origin).pathname);const active=href===path||(path==='/project'&&href==='/work')||(path==='/album'&&href==='/photography')||(path.startsWith('/photography/')&&href==='/photography')||(path.startsWith('/share/photography/')&&href==='/photography');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page')})}
document.addEventListener('DOMContentLoaded',()=>{loadSettings();loadProjects('#featuredProjects',true);loadProjects();loadAlbums();loadProject();loadAlbum();loadHomeStats();initActiveNav();const nav=$('.nav-links'),b=$('.menu-btn');if(b&&nav)b.onclick=()=>{const open=nav.classList.toggle('open');b.setAttribute('aria-expanded',String(open))};$('#lightboxClose')?.addEventListener('click',closeLightbox);$('#lightboxPrev')?.addEventListener('click',()=>moveLightbox(-1));$('#lightboxNext')?.addEventListener('click',()=>moveLightbox(1));$('#lightbox')?.addEventListener('click',e=>{if(e.target.id==='lightbox')closeLightbox()});$('#lightbox')?.addEventListener('touchstart',e=>{touchStartX=e.changedTouches[0].clientX;touchStartY=e.changedTouches[0].clientY},{passive:true});$('#lightbox')?.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-touchStartX,dy=e.changedTouches[0].clientY-touchStartY;if(Math.abs(dx)>48&&Math.abs(dx)>Math.abs(dy)*1.4){moveLightbox(dx<0?1:-1);return}if(Math.abs(dx)<12&&Math.abs(dy)<12){const now=Date.now();if(now-lastTap<320)likeCurrent(true);lastTap=now}},{passive:true});window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search).get('photo');if(p&&currentAlbum&&lightboxItems.length){const idx=lightboxItems.findIndex(x=>x.id===p);if(idx>=0){lightboxIndex=idx;$('#lightbox')?.classList.add('open');renderLightbox();return}}if($('#lightbox')?.classList.contains('open')){$('#lightbox').classList.remove('open');document.body.style.overflow='';closeDesktopHandoff()}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#storyHandoffModal')?.classList.contains('open')){closeDesktopHandoff();return}if(!$('#lightbox')?.classList.contains('open'))return;if(e.key==='Escape')closeLightbox();if(e.key==='ArrowRight')moveLightbox(1);if(e.key==='ArrowLeft')moveLightbox(-1)})})
document.addEventListener('DOMContentLoaded',loadFeaturedPhotography)
